import re
from typing import List, Dict, Any, Union

# ------------------------------------------------------------
# Helper functions are assumed to already exist in the environment
# ------------------------------------------------------------
# node_by_title(doc, title), node_by_id(doc, node_id),
# children(doc, node), table_rows(node) -> [(row_index, {column:cell})]
# ------------------------------------------------------------

def _parse_int(cell: str) -> int:
    """Parse an integer from a cell, treating missing or non‑numeric values as 0."""
    try:
        return int(cell.replace(",", "").strip())
    except Exception:
        return 0

def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return all distinct product entities described in the scope."""
    prod_node = node_by_title(doc, f"{scope}: Products")
    rows = table_rows(prod_node)
    result = []
    for _, row in rows:
        pid = row["product"]
        description = f"{pid} ({row['group']}-{row['sub-group']})"
        result.append({"id": pid, "description": description})
    return result

def recorded_end(doc: Dict[str, Any], scope: str) -> Union[float, None]:
    """
    Return the last day number represented in any table within the scope.
    If no dated data exists, return None.
    """
    max_day = None

    # Ledger days
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for idx, row in table_rows(ledger_node):
            d = _parse_int(row["day"])
            if max_day is None or d > max_day:
                max_day = d

    # Order book days
    ob_node = node_by_title(doc, f"{scope}: Order book")
    if ob_node:
        cols = ob_node["table"]["columns"]
        for idx, row in table_rows(ob_node):
            if "day" in cols:
                d = _parse_int(row["day"])
            elif "day placed" in cols:
                d = _parse_int(row["day placed"])
            else:
                continue
            if max_day is None or d > max_day:
                max_day = d

    return float(max_day) if max_day is not None else None

def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """External inputs to the process within the given scope."""
    out = []

    prod_node = node_by_title(doc, f"{scope}: Products")
    rows = table_rows(prod_node)
    for row_idx, row in rows:
        pid = row["product"]
        opening = _parse_int(row["opening stock"])
        out.append({
            "id": f"open_stock_{pid}",
            "time": 0.0,
            "kind": "state",
            "entities": [pid],
            "fields": {"opening_stock": opening},
            "src": [[prod_node["node_id"], row_idx, ["opening stock"]]]
        })

    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for row_idx, row in table_rows(ledger_node):
            pid = row["product"]
            day = _parse_int(row["day"])
            prod_qty = _parse_int(row["produced"])
            order_qty = _parse_int(row["ordered"])

            # Production input
            if prod_qty > 0:
                out.append({
                    "id": f"prod_{pid}_day{day}",
                    "time": float(day),
                    "kind": "production",
                    "entities": [pid],
                    "fields": {"produced": prod_qty},
                    "src": [[ledger_node["node_id"], row_idx, ["produced"]]]
                })

            # Order placement input (only if >0 to avoid silent 0‑orders)
            if order_qty > 0:
                out.append({
                    "id": f"order_{pid}_day{day}",
                    "time": float(day),
                    "kind": "order_placement",
                    "entities": [pid],
                    "fields": {"ordered": order_qty},
                    "src": [[ledger_node["node_id"], row_idx, ["ordered"]]]
                })

    ob_node = node_by_title(doc, f"{scope}: Order book")
    if ob_node:
        cols = ob_node["table"]["columns"]
        for row_idx, row in table_rows(ob_node):
            # Shape that has product, day placed, units still open
            if "product" in cols and "day placed" in cols and "units still open" in cols:
                pid = row["product"]
                day = _parse_int(row["day placed"])
                uoo = _parse_int(row["units still open"])
                out.append({
                    "id": f"open_order_{pid}_day{day}",
                    "time": float(day),
                    "kind": "open_order",
                    "entities": [pid],
                    "fields": {"open_units": uoo},
                    "src": [[ob_node["node_id"], row_idx, ["units still open"]]]
                })
            # Shape that has day, product, ordered, (planned production)
            elif "product" in cols and ("ordered" in cols or "planned production" in cols):
                pid = row["product"]
                day = _parse_int(row.get("day", row.get("day placed", 0)))
                # Future order
                if "ordered" in cols:
                    order_qty = _parse_int(row["ordered"])
                    if order_qty > 0:
                        out.append({
                            "id": f"order_{pid}_day{day}",
                            "time": float(day),
                            "kind": "order_placement",
                            "entities": [pid],
                            "fields": {"ordered": order_qty},
                            "src": [[ob_node["node_id"], row_idx, ["ordered"]]]
                        })
                # Scheduled production
                if "planned production" in cols:
                    prod_qty = _parse_int(row["planned production"])
                    if prod_qty > 0:
                        out.append({
                            "id": f"schedule_prod_{pid}_day{day}",
                            "time": float(day),
                            "kind": "scheduled_production",
                            "entities": [pid],
                            "fields": {"planned_production": prod_qty},
                            "src": [[ob_node["node_id"], row_idx, ["planned production"]]]
                        })

    return out

def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """All outcomes recorded in the scope."""
    out = []

    # Ledger values that are outcomes (shipped, backordered, stock)
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for row_idx, row in table_rows(ledger_node):
            pid = row["product"]
            day = _parse_int(row["day"])
            for col in ("shipped", "backordered", "stock"):
                if col in row:
                    val = _parse_int(row[col])
                    out.append({
                        "time": float(day),
                        "kind": col,
                        "entities": [pid],
                        "value": val,
                        "src": [[ledger_node["node_id"], row_idx, [col]]]
                    })

    # Events
    events_node = node_by_title(doc, f"{scope}: Events")
    if events_node:
        for li, line in enumerate(events_node.get("lines", [])):
            m_day = re.search(r"Day\s+(\d+)", line)
            day = float(m_day.group(1)) if m_day else None

            # Dispatch capacity reached
            if "dispatch capacity reached" in line.lower():
                out.append({
                    "time": day,
                    "kind": "capacity_reached",
                    "entities": [],
                    "value": None,
                    "src": [[events_node["node_id"], li]]
                })

            # Product runs out of stock
            m_run = re.search(r"(\w+?)\s+runs\s+out\s+of\s+stock", line)
            if m_run:
                pid = m_run.group(1)
                out.append({
                    "time": day,
                    "kind": "run_out_of_stock",
                    "entities": [pid],
                    "value": None,
                    "src": [[events_node["node_id"], li]]
                })

            # Order fully backordered
            m_back = re.search(r"(\w+?)\s+order\s+fully\s+backordered", line)
            pid = m_back.group(1) if m_back else None
            if "order fully backordered" in line.lower():
                out.append({
                    "time": day,
                    "kind": "order_fully_backordered",
                    "entities": [pid] if pid else [],
                    "value": None,
                    "src": [[events_node["node_id"], li]]
                })

            # Backlog cleared
            m_clear = re.search(r"(\w+?)\s+backlog\s+cleared", line)
            pid = m_clear.group(1) if m_clear else None
            if "backlog cleared" in line.lower():
                out.append({
                    "time": day,
                    "kind": "backlog_cleared",
                    "entities": [pid] if pid else [],
                    "value": None,
                    "src": [[events_node["node_id"], li]]
                })

    return out

def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return constants that the document explicitly states."""
    result: Dict[str, Any] = {}

    # Dispatch capacity
    scope_node = node_by_title(doc, scope)
    if scope_node:
        txt = scope_node.get("text", "")
        cap_match = re.search(r"Daily dispatch capacity:\s*([\d,]+)\s*kg", txt)
        if cap_match:
            cap = int(cap_match.group(1).replace(",", ""))
            result["dispatch_capacity_kg"] = cap

    # Product weights (kg per unit)
    prod_node = node_by_title(doc, f"{scope}: Products")
    if prod_node:
        weights = {}
        for _, row in table_rows(prod_node):
            pid = row["product"]
            w = _parse_int(row["kg per unit"])
            weights[pid] = w
        if weights:
            result["product_weights_kg"] = weights

    return result

import re
from typing import List, Dict, Any, Union

# The following helper functions are assumed to already exist in the environment:
# node_by_title(doc, title), node_by_id(doc, node_id),
# children(doc, node), table_rows(node) -> [(row_index, {column:cell})]

# ------------------------------------------------------------------
# General helpers
# ------------------------------------------------------------------
def _parse_int(cell: str) -> int:
    """Parse an integer from a cell, treating commas and missing values as 0."""
    try:
        return int(cell.replace(",", "").strip())
    except Exception:
        return 0

def _product_id(row: Dict[str, str]) -> str:
    return row["product"]

def _day_value(row: Dict[str, str], cols: List[str]) -> int:
    for c in ("day", "day placed", "day placed"):
        if c in cols:
            return _parse_int(row[c])
    return 0

# ------------------------------------------------------------------
# Entities
# ------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return all distinct product entities described in the scope."""
    prod_node = node_by_title(doc, f"{scope}: Products")
    if not prod_node:
        return []

    rows = table_rows(prod_node)
    ents = []
    for _, row in rows:
        pid = row["product"]
        grp = row.get("group", "")
        subgroup = row.get("sub-group", "")
        description = f"{pid} ({grp}-{subgroup})"
        ents.append({"id": pid, "description": description})
    return ents

