def recorded_end(doc: Dict[str, Any], scope: str) -> Union[float, None]:
    """Return the last day number represented in any table within the scope."""
    max_day = None

    # Ledger days
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for _, row in table_rows(ledger_node):
            d = _parse_int(row["day"])
            if max_day is None or d > max_day:
                max_day = d

    # Order book days
    ob_node = node_by_title(doc, f"{scope}: Order book")
    if ob_node:
        cols = ob_node["table"]["columns"]
        for _, row in table_rows(ob_node):
            if "day" in cols:
                d = _parse_int(row["day"])
            elif "day placed" in cols:
                d = _parse_int(row["day placed"])
            else:
                continue
            if max_day is None or d > max_day:
                max_day = d

    return float(max_day) if max_day is not None else None

# ------------------------------------------------------------------
# Inputs
# ------------------------------------------------------------------
def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    out = []

    # ----------------- Opening stock -----------------
    prod_node = node_by_title(doc, f"{scope}: Products")
    if prod_node:
        for row_index, row in table_rows(prod_node):
            pid = _product_id(row)
            opening = _parse_int(row["opening stock"])
            out.append({
                "id": f"open_stock_{pid}",
                "time": 0.0,
                "kind": "state",
                "entities": [pid],
                "fields": {"opening_stock": opening},
                "src": [[prod_node["node_id"], row_index,
                         ["product", "opening stock"]]]
            })

    # ----------------- Daily ledger inputs -----------------
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for row_index, row in table_rows(ledger_node):
            pid = _product_id(row)
            day = _parse_int(row["day"])
            produced = _parse_int(row["produced"])
            ordered = _parse_int(row["ordered"])

            if produced > 0:
                out.append({
                    "id": f"prod_{pid}_day{day}",
                    "time": float(day),
                    "kind": "production",
                    "entities": [pid],
                    "fields": {"produced": produced},
                    "src": [[ledger_node["node_id"], row_index,
                             ["product", "day", "produced"]]]
                })
            if ordered > 0:
                out.append({
                    "id": f"order_{pid}_day{day}",
                    "time": float(day),
                    "kind": "order_placement",
                    "entities": [pid],
                    "fields": {"ordered": ordered},
                    "src": [[ledger_node["node_id"], row_index,
                             ["product", "day", "ordered"]]]
                })

    # ----------------- Order book inputs -----------------
    ob_node = node_by_title(doc, f"{scope}: Order book")
    if ob_node:
        cols = ob_node["table"]["columns"]
        for row_index, row in table_rows(ob_node):
            pid = _product_id(row)

            # Initial open order
            if "day placed" in cols and "units still open" in cols:
                day = _parse_int(row["day placed"])
                uoo = _parse_int(row["units still open"])
                out.append({
                    "id": f"open_order_{pid}_day{day}",
                    "time": float(day),
                    "kind": "open_order",
                    "entities": [pid],
                    "fields": {"open_units": uoo},
                    "src": [[ob_node["node_id"], row_index,
                             ["product", "day placed", "units still open"]]]
                })

            # Future order placement
            if ("day" in cols or "day placed" in cols) and "ordered" in cols:
                day = _parse_int(row.get("day", row.get("day placed", 0)))
                order_qty = _parse_int(row["ordered"])
                if order_qty > 0:
                    out.append({
                        "id": f"future_order_{pid}_day{day}",
                        "time": float(day),
                        "kind": "order_placement",
                        "entities": [pid],
                        "fields": {"ordered": order_qty},
                        "src": [[ob_node["node_id"], row_index,
                                 ["product", "day" if "day" in cols else "day placed", "ordered"]]]
                    })

            # Scheduled production
            if ("day" in cols or "day placed" in cols) and "planned production" in cols:
                day = _parse_int(row.get("day", row.get("day placed", 0)))
                prod_qty = _parse_int(row["planned production"])
                if prod_qty > 0:
                    out.append({
                        "id": f"scheduled_prod_{pid}_day{day}",
                        "time": float(day),
                        "kind": "scheduled_production",
                        "entities": [pid],
                        "fields": {"planned_production": prod_qty},
                        "src": [[ob_node["node_id"], row_index,
                                 ["product", "day" if "day" in cols else "day placed", "planned production"]]]
                    })

    return out

