def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    out = []

    # Ledger outcomes: shipped, backordered, stock
    ledger_node = node_by_title(doc, f"{scope}: Daily ledger")
    if ledger_node:
        for row_index, row in table_rows(ledger_node):
            pid = _product_id(row)
            day = _parse_int(row["day"])
            for col in ("shipped", "backordered", "stock"):
                if col in row:
                    val = _parse_int(row[col])
                    out.append({
                        "time": float(day),
                        "kind": col,
                        "entities": [pid],
                        "value": val,
                        "src": [[ledger_node["node_id"], row_index,
                                 ["product", "day", col]]]
                    })

    # Events
    events_node = node_by_title(doc, f"{scope}: Events")
    if events_node:
        for li, line in enumerate(events_node.get("lines", [])):
            m_day = re.search(r"Day\s+(\d+)", line)
            day = float(m_day.group(1)) if m_day else None

            # Capacity reached
            if "dispatch capacity reached" in line.lower():
                out.append({
                    "time": day,
                    "kind": "capacity_reached",
                    "entities": [],
                    "value": None,
                    "src": [[events_node["node_id"], li]]
                })

            # Product runs out of stock
            m_run = re.search(r"([A-Za-z0-9-]+)\s+runs\s+out\s+of\s+stock", line)
            if m_run:
                pid = m_run.group(1)
                out.append({
                    "time": day,
                    "kind": "run_out_of_stock",
                    "entities": [pid],
                    "value": None,
                    "src": [[events_node["node_id"], li]]
                })

            # Order fully backordered
            m_back = re.search(r"([A-Za-z0-9-]+)\s+order\s+fully\s+backordered", line)
            if m_back:
                pid = m_back.group(1)
                out.append({
                    "time": day,
                    "kind": "order_fully_backordered",
                    "entities": [pid],
                    "value": None,
                    "src": [[events_node["node_id"], li]]
                })

            # Backlog cleared
            m_clear = re.search(r"([A-Za-z0-9-]+)\s+backlog\s+cleared", line)
            if m_clear:
                pid = m_clear.group(1)
                out.append({
                    "time": day,
                    "kind": "backlog_cleared",
                    "entities": [pid],
                    "value": None,
                    "src": [[events_node["node_id"], li]]
                })

    return out

