def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    result: Dict[str, Any] = {}

    scope_node = node_by_title(doc, scope)
    if scope_node and "text" in scope_node:
        txt = scope_node["text"]
        # Daily dispatch capacity
        cap_match = re.search(r"Daily dispatch capacity:\s*([\d,]+)\s*kg", txt)
        if cap_match:
            cap = int(cap_match.group(1).replace(",", ""))
            result["dispatch_capacity_kg"] = cap

    # Product weights per unit
    prod_node = node_by_title(doc, f"{scope}: Products")
    if prod_node:
        weights = {}
        for _, row in table_rows(prod_node):
            pid = _product_id(row)
            w = _parse_int(row["kg per unit"])
            weights[pid] = w
        if weights:
            result["product_weights_kg"] = weights

    return result
